"""Fork-only patch transport for PR #107713 validation."""
from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import subprocess

PAYLOAD = """"""
SHA256 = "c87266021b5a5c395f082e48b272ca5544e79a361527750fb49ed0670a3653c3"
TEST_PATHS = [
    "apps/desktop/src/api/mcp-network.test.ts",
    "apps/desktop/src/lib/mcp-probe-cache.test.ts",
    "tests/hermes_cli/test_mcp_network_surfaces.py",
    "tests/tools/test_mcp_network_oauth.py",
    "tests/tools/test_mcp_windows.py",
    "tests/tools/test_mcp_windows_policy.py",
    "web/src/lib/mcp-network.test.ts",
]

parser = argparse.ArgumentParser()
parser.add_argument("--tests-only", action="store_true")
args = parser.parse_args()
patch = gzip.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(patch).hexdigest() == SHA256
command = ["git", "apply", "--whitespace=nowarn"]
if args.tests_only:
    for path in TEST_PATHS:
        command.extend(["--include", path])
subprocess.run(command, input=patch, check=True)
